  ring_of_evasion: { name: 'Ring of Evasion', rarity: 'rare', attune: true, slot: 'ring', art: 'ring', cols: ['#c8c8d8', '#5a5a6a', '#a0e0ff'], wear: { adv: ['dex_save'] }, todo: 'SRD: 3 charges; spend one to turn a failed Dexterity save into a success', desc: 'It tugs you out of harm\'s way: advantage on Dexterity saving throws.' },
  ring_of_feather_falling: { name: 'Ring of Feather Falling', rarity: 'rare', attune: true, slot: 'ring', art: 'ring', cols: ['#e0e8f0', '#7a8a9a', '#ffffff'], wear: { featherFall: true }, desc: 'You drift down gently whenever you fall, taking no damage.' },
  ring_of_free_action: { name: 'Ring of Free Action', rarity: 'rare', attune: true, slot: 'ring', art: 'ring', cols: ['#e0c060', '#7a5a10', '#a0ffd0'], wear: { freedom: true }, desc: 'Nothing can slow, hold or root you, and water doesn\'t hold you back.' },
  ring_of_invisibility: { name: 'Ring of Invisibility', rarity: 'legendary', attune: true, slot: 'ring', art: 'ring', cols: ['#f0d060', '#8a6a10', '#ffffff'], wear: { invisible: 'use' }, desc: 'Turn invisible whenever you like, until you attack or cast a spell.' },
  ring_of_jumping: { name: 'Ring of Jumping', rarity: 'uncommon', attune: true, slot: 'ring', art: 'ring', cols: ['#a0c860', '#4a6a1a', '#e8ffc0'], wear: { jump: 3 }, desc: 'You jump three times as far.' },
