  ring_of_resistance_cold: { name: 'Ring of Resistance (Cold, Tourmaline)', rarity: 'rare', attune: false, slot: 'ring', art: 'ring', cols: ['#d8c8a0', '#6a5a30', '#40c0b0'], wear: { resist: ['cold'] }, desc: 'A tourmaline ring: resistance to cold damage.' },
  ring_of_resistance_fire: { name: 'Ring of Resistance (Fire, Garnet)', rarity: 'rare', attune: false, slot: 'ring', art: 'ring', cols: ['#d8c8a0', '#6a5a30', '#c0202a'], wear: { resist: ['fire'] }, desc: 'A garnet ring: resistance to fire damage.' },
  ring_of_resistance_force: { name: 'Ring of Resistance (Force, Sapphire)', rarity: 'rare', attune: false, slot: 'ring', art: 'ring', cols: ['#d8c8a0', '#6a5a30', '#2a4ad8'], wear: { resist: ['force'] }, desc: 'A sapphire ring: resistance to force damage.' },
  ring_of_resistance_lightning: { name: 'Ring of Resistance (Lightning, Citrine)', rarity: 'rare', attune: false, slot: 'ring', art: 'ring', cols: ['#d8c8a0', '#6a5a30', '#f0c030'], wear: { resist: ['lightning'] }, desc: 'A citrine ring: resistance to lightning damage.' },
  ring_of_resistance_necrotic: { name: 'Ring of Resistance (Necrotic, Jet)', rarity: 'rare', attune: false, slot: 'ring', art: 'ring', cols: ['#d8c8a0', '#6a5a30', '#2a2a30'], wear: { resist: ['necrotic'] }, desc: 'A jet ring: resistance to necrotic damage.' },
  ring_of_resistance_poison: { name: 'Ring of Resistance (Poison, Amethyst)', rarity: 'rare', attune: false, slot: 'ring', art: 'ring', cols: ['#d8c8a0', '#6a5a30', '#9a5ad8'], wear: { resist: ['poison'] }, desc: 'An amethyst ring: resistance to poison damage.' },
  ring_of_resistance_psychic: { name: 'Ring of Resistance (Psychic, Jade)', rarity: 'rare', attune: false, slot: 'ring', art: 'ring', cols: ['#d8c8a0', '#6a5a30', '#3aa86a'], wear: { resist: ['psychic'] }, desc: 'A jade ring: resistance to psychic damage.' },
  ring_of_resistance_radiant: { name: 'Ring of Resistance (Radiant, Topaz)', rarity: 'rare', attune: false, slot: 'ring', art: 'ring', cols: ['#d8c8a0', '#6a5a30', '#f0a030'], wear: { resist: ['radiant'] }, desc: 'A topaz ring: resistance to radiant damage.' },
  ring_of_resistance_thunder: { name: 'Ring of Resistance (Thunder, Spinel)', rarity: 'rare', attune: false, slot: 'ring', art: 'ring', cols: ['#d8c8a0', '#6a5a30', '#d03a6a'], wear: { resist: ['thunder'] }, desc: 'A spinel ring: resistance to thunder damage.' },
