  ring_of_telekinesis: { name: 'Ring of Telekinesis', rarity: 'very_rare', attune: true, slot: 'ring', art: 'ring', cols: ['#c0a0e0', '#4a2a7a', '#f8f0ff'], cast: 'telekinesis', charges: 'long', desc: 'Move creatures and things with your mind.' },
