  ring_of_three_wishes: { name: 'Ring of Three Wishes', rarity: 'legendary', attune: false, slot: 'ring', art: 'ring', cols: ['#f0d060', '#8a6a10', '#ff6a8a'], cast: 'wish', charges: 3, desc: 'Three stars glint in the ring. Each one is a Wish.' },
  ring_of_warmth: { name: 'Ring of Warmth', rarity: 'uncommon', attune: true, slot: 'ring', art: 'ring', cols: ['#e0a040', '#7a4a10', '#ff7a3a'], wear: { resist: ['cold'] }, desc: 'You resist cold damage and never feel the chill of winter.' },
  ring_of_water_walking: { name: 'Ring of Water Walking', rarity: 'uncommon', attune: false, slot: 'ring', art: 'ring', cols: ['#7ab8e0', '#1a4a6a', '#e8f8ff'], cast: 'water_walk', charges: 'long', desc: 'Walk on water and other liquids as if they were solid ground.' },
  ring_of_x_ray_vision: { name: 'Ring of X-ray Vision', rarity: 'rare', attune: true, slot: 'ring', art: 'ring', cols: ['#c8c8d0', '#5a5a64', '#a0ffa0'], cast: 'see_invisibility', charges: 'long', todo: 'should let you see through 6 blocks of solid stone (creatures and hidden doors behind walls) for a minute', desc: 'Once per rest, see through solid walls and find what hides behind them.' },

